package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParseException;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.BufferRecycler;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.*;
import com.fasterxml.jackson.core.util.*;
import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for UTF8StreamJsonParser._parseNumber
 */
public class UTF8StreamJsonParser__parseNumber_TriageGen1Test {

    private static final int INT_MINUS = '-';
    private static final int INT_0 = '0';
    private static final int INT_9 = '9';

    private IOContext ctxt;

    @Before
    public void setUp() {
        ctxt = IOContext.bootstrap();
    }

    /**
     * Helper to create a parser instance.
     * Since _parseNumber is protected, we use a subclass or test within the same package.
     */
    private TestableParser createParser(byte[] input) {
        return new TestableParser(ctxt, 0, new ByteArrayInputStream(input), null, null, input, 0, input.length, true);
    }

    /**
     * Subclass to expose protected method for testing.
     */
    private static class TestableParser extends UTF8StreamJsonParser {
        public TestableParser(IOContext ctxt, int features, InputStream in, ObjectCodec codec, 
                             BytesToNameCanonicalizer sym, byte[] inputBuffer, int start, int end, boolean bufferRecyclable) {
            super(ctxt, features, in, codec, sym, inputBuffer, start, end, bufferRecyclable);
        }

        public JsonToken publicParseNumber(int c) throws IOException, JsonParseException {
            return _parseNumber(c);
        }
    }

    @Test
    public void testParsePositiveInteger() throws IOException, JsonParseException {
        byte[] input = "123".getBytes();
        TestableParser parser = createParser(input);
        // The first digit is passed as 'c'
        JsonToken token = parser.publicParseNumber('1');
        assertEquals(JsonToken.VALUE_NUMBER_INT, token);
        assertEquals("123", parser.getValueAsString());
    }

    @Test
    public void testParseNegativeInteger() throws IOException, JsonParseException {
        byte[] input = "-123".getBytes();
        TestableParser parser = createParser(input);
        // Pass '-' as 'c'
        JsonToken token = parser.publicParseNumber('-');
        assertEquals(JsonToken.VALUE_NUMBER_INT, token);
        assertEquals("-123", parser.getValueAsString());
    }

    @Test
    public void testParseNegativeInvalidStart() throws IOException {
        byte[] input = "-a".getBytes();
        TestableParser parser = createParser(input);
        try {
            parser.publicParseNumber('-');
        } catch (JsonParseException e) {
            // Expected: must be followed by a digit
        }
    }

    @Test
    public void testParseZero() throws IOException, JsonParseException {
        byte[] input = "0".getBytes();
        TestableParser parser = createParser(input);
        JsonToken token = parser.publicParseNumber('0');
        assertEquals(JsonToken.VALUE_NUMBER_INT, token);
        assertEquals("0", parser.getValueAsString());
    }

    @Test
    public void testParseLeadingZeroInvalid() throws IOException {
        byte[] input = "0123".getBytes();
        TestableParser parser = createParser(input);
        try {
            parser.publicParseNumber('0');
        } catch (JsonParseException e) {
            // Expected: _verifyNoLeadingZeroes should fail if followed by digit
        }
    }

    @Test
    public void testParseFloatWithDot() throws IOException, JsonParseException {
        byte[] input = "123.45".getBytes();
        TestableParser parser = createParser(input);
        JsonToken token = parser.publicParseNumber('1');
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, token);
        assertEquals("123.45", parser.getValueAsString());
    }

    @Test
    public void testParseFloatWithExponentE() throws IOException, JsonParseException {
        byte[] input = "123E10".getBytes();
        TestableParser parser = createParser(input);
        JsonToken token = parser.publicParseNumber('1');
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, token);
        assertEquals("123E10", parser.getValueAsString());
    }

    @Test
    public void testParseFloatWithExponentSmallE() throws IOException, JsonParseException {
        byte[] input = "123e10".getBytes();
        TestableParser parser = createParser(input);
        JsonToken token = parser.publicParseNumber('1');
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, token);
        assertEquals("123e10", parser.getValueAsString());
    }

    @Test
    public void testParseLargeNumberTriggeringBufferSplit() throws IOException, JsonParseException {
        // Create a very long number to force the 'outPtr >= outBuf.length' condition
        // and the '_parserNumber2' branch.
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 1000; i++) {
            sb.append('1');
        }
        byte[] input = sb.toString().getBytes();
        TestableParser parser = createParser(input);

        JsonToken token = parser.publicParseNumber('1');
        assertEquals(JsonToken.VALUE_NUMBER_INT, token);
        assertEquals(1000, parser.getValueAsString().length());
    }

    @Test
    public void testParseNumberWithTrailingChar() throws IOException, JsonParseException {
        // Test the '--_inputPtr' logic where a non-digit follows the number
        byte[] input = "123,".getBytes();
        TestableParser parser = createParser(input);
        JsonToken token = parser.publicParseNumber('1');
        assertEquals(JsonToken.VALUE_NUMBER_INT, token);
        assertEquals("123", parser.getValueAsString());
    }

    @Test
    public void testParseNegativeZero() throws IOException, JsonParseException {
        // Depending on implementation, -0 might be treated as integer or float
        byte[] input = "-0".getBytes();
        TestableParser parser = createParser(input);
        JsonToken token = parser.publicParseNumber('-');
        // In Jackson, -0 is usually parsed as an integer if no decimal is present
        assertEquals(JsonToken.VALUE_NUMBER_INT, token);
        assertEquals("-0", parser.getValueAsString());
    }
}
